SELECT CASE WHEN m.entry_quality_score < 55 THEN 'EQ50-54' WHEN m.entry_quality_score < 70 THEN 'EQ55-69' WHEN m.entry_quality_score < 85 THEN 'EQ70-84' ELSE 'EQ85+' END AS eq_bucket, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losers, ROUND(SUM(p.realized_pnl),6) AS pnl_sum, ROUND(AVG(s.risk_reward_ratio),3) AS avg_rr FROM crypto_ai.wallet_managed_position m JOIN crypto_ai.paper_position p ON p.signal_id=m.entry_signal_id JOIN crypto_ai.trade_signal s ON s.id=m.entry_signal_id WHERE p.status IN ('CLOSED','STOPPED') GROUP BY eq_bucket ORDER BY eq_bucket;
SELECT CASE WHEN (p.take_profit-p.entry_price)/p.entry_price*100 < 0.20 THEN 'TP<0.20%' WHEN (p.take_profit-p.entry_price)/p.entry_price*100 < 0.40 THEN 'TP0.20-0.40%' ELSE 'TP>=0.40%' END AS tp_bucket, p.status, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losers, ROUND(SUM(p.realized_pnl),6) AS pnl_sum FROM crypto_ai.paper_position p WHERE p.status IN ('CLOSED','STOPPED') GROUP BY tp_bucket, p.status ORDER BY tp_bucket, p.status;